do $$ declare v_governance_ready integer; begin select count(*) into v_governance_ready from runtime_config_inventory_governance where configuration_key in ('core.integration-events.batch-size','core.integration-events.claim-lease','core.integration-events.endpoint-url','core.integration-events.exported-event-types','core.integration-events.initial-backoff','core.integration-events.max-attempts','core.integration-events.max-backoff','core.integration-events.request-timeout','core.integration-events.scan-interval-ms','core.integration-events.sink','core.integration-events.source','core.integration-events.worker-id','core.outbox.batch-size','core.outbox.claim-lease','core.outbox.initial-backoff','core.outbox.max-attempts','core.outbox.max-backoff','core.outbox.scan-interval-ms','core.outbox.worker-id') and status='MIGRATION_READY' and classified_by is not null and owner_reviewed_by is not null and architecture_approved_by is not null and migration_authorized_by='v41-c3r2l-core-outbox-integration-events-consumer-closure'; if v_governance_ready<>19 then raise exception 'C3R2L_GOVERNANCE_LIFECYCLE_INCOMPLETE expected=19 actual=%',v_governance_ready; end if; end $$;

do $$ declare v_ready integer; begin
select count(*) into v_ready from runtime_config_definitions where definition_key in ('core.integration-events.batch-size','core.integration-events.claim-lease','core.integration-events.endpoint-url','core.integration-events.exported-event-types','core.integration-events.initial-backoff','core.integration-events.max-attempts','core.integration-events.max-backoff','core.integration-events.request-timeout','core.integration-events.scan-interval-ms','core.integration-events.sink','core.integration-events.source','core.integration-events.worker-id','core.outbox.batch-size','core.outbox.claim-lease','core.outbox.initial-backoff','core.outbox.max-attempts','core.outbox.max-backoff','core.outbox.scan-interval-ms','core.outbox.worker-id') and review_status='MIGRATION_READY' and migration_authorized=true and admin_editable=true;
if v_ready<>19 then raise exception 'C3R2L_DOMAIN_DEFINITION_CLOSURE_INCOMPLETE expected=19 actual=%',v_ready; end if;
if exists(select 1 from runtime_config_definitions where definition_key in ('core.integration-events.batch-size','core.integration-events.claim-lease','core.integration-events.endpoint-url','core.integration-events.exported-event-types','core.integration-events.initial-backoff','core.integration-events.max-attempts','core.integration-events.max-backoff','core.integration-events.request-timeout','core.integration-events.scan-interval-ms','core.integration-events.sink','core.integration-events.source','core.integration-events.worker-id','core.outbox.batch-size','core.outbox.claim-lease','core.outbox.initial-backoff','core.outbox.max-attempts','core.outbox.max-backoff','core.outbox.scan-interval-ms','core.outbox.worker-id') and config_set_key<>'RUNTIME/CORE/SYSTEM') then raise exception 'C3R2L_CORE_CONFIG_SET_KEY_MISMATCH'; end if;
if exists(select 1 from runtime_config_inventory_governance where configuration_key in ('core.integration-events.batch-size','core.integration-events.claim-lease','core.integration-events.endpoint-url','core.integration-events.exported-event-types','core.integration-events.initial-backoff','core.integration-events.max-attempts','core.integration-events.max-backoff','core.integration-events.request-timeout','core.integration-events.scan-interval-ms','core.integration-events.sink','core.integration-events.source','core.integration-events.worker-id','core.outbox.batch-size','core.outbox.claim-lease','core.outbox.initial-backoff','core.outbox.max-attempts','core.outbox.max-backoff','core.outbox.scan-interval-ms','core.outbox.worker-id') and status in ('MIGRATED','LEGACY_RETIRED')) then raise exception 'C3R2L_PREMATURE_SINGLE_AUTHORITY_CUTOVER'; end if;
if exists(select 1 from runtime_config_definitions where definition_key in ('core.outbox.batch-size','core.outbox.claim-lease','core.outbox.initial-backoff','core.outbox.max-attempts','core.outbox.max-backoff','core.outbox.scan-interval-ms','core.outbox.worker-id') and validation_rule is null) then raise exception 'C3R2L_OUTBOX_VALIDATION_MISSING'; end if;
if exists(select 1 from runtime_config_definitions where definition_key in ('core.integration-events.batch-size','core.integration-events.claim-lease','core.integration-events.endpoint-url','core.integration-events.exported-event-types','core.integration-events.initial-backoff','core.integration-events.max-attempts','core.integration-events.max-backoff','core.integration-events.request-timeout','core.integration-events.scan-interval-ms','core.integration-events.sink','core.integration-events.source','core.integration-events.worker-id') and validation_rule is null) then raise exception 'C3R2L_INTEGRATION_VALIDATION_MISSING'; end if;
end $$;
